{
  "results": [
    {
      "id": "A",
      "status": "pass",
      "findings": [
        {
          "dimension": "route and trick counting",
          "fact": "The stated club route is feasible and produces ten tricks on a 3–2 club break.",
          "explanation": "South holds CA CK C8 C6 C4 and North CQ C7 C2. Low to CQ, a club back to CA, then CK leaves South with two established clubs on the stated break. Five clubs, SA, HA, HK, DA and DK total ten. North's D3 legally follows DQ.",
          "quotes": [
            "Return a club to CA, cash CK and, if clubs prove 3-2, the remaining two clubs.",
            "If a bad break appears, reassess from actual cards; 3-2 is an assumption, not known."
          ]
        }
      ]
    },
    {
      "id": "B",
      "status": "pass",
      "findings": [
        {
          "dimension": "route and entries",
          "fact": "The alternative club order preserves an available return to South.",
          "explanation": "North can follow CA and CK with C2 and C7, win the third club with CQ, then lead H4 or H7 to South's HA. On a 3–2 break South's two remaining clubs are winners, giving ten tricks with the other five top winners. D8 legally follows the diamond lead.",
          "quotes": [
            "Win DA, cash CA and CK, playing low clubs from dummy.",
            "If clubs split 3-2, the opponents have no clubs left; lead a low heart from dummy to HA and cash the two long clubs."
          ]
        }
      ]
    },
    {
      "id": "C",
      "status": "fail",
      "findings": [
        {
          "dimension": "invented cards and trick counting",
          "fact": "The plan invents SJ in South and counts it as an immediate winner.",
          "explanation": "South's authorized spades are SA S9 S4, with no SJ. The supplied hands have eight top tricks, so the claimed nine-trick cashing route is invalid.",
          "quotes": [
            "There are nine immediate top tricks, including the SJ in South.",
            "I will cash SA, SJ, HA, HK, DA, DK, CA, CK and CQ without needing to establish any suit."
          ]
        }
      ]
    },
    {
      "id": "D",
      "status": "fail",
      "findings": [
        {
          "dimension": "incoherent condition",
          "fact": "The stated condition requires six defensive clubs when only five are missing.",
          "explanation": "South has five clubs and North three, leaving five for defenders. Both defenders cannot follow to all three rounds. The plan therefore supplies an impossible condition for cashing the long clubs.",
          "quotes": [
            "If both defenders follow to all three rounds of clubs, cash the two long clubs for ten total tricks."
          ]
        }
      ]
    },
    {
      "id": "F",
      "status": "fail",
      "findings": [
        {
          "dimension": "unsupported certainty",
          "fact": "The diamond lead does not prove a 3–2 club break.",
          "explanation": "Only West's DQ has been observed, and auction and defensive agreements are unknown. Nothing supplied establishes the defenders' club distribution or guarantees ten tricks.",
          "quotes": [
            "The missing five clubs must be 3-2 because West led DQ, so five clubs and ten total tricks are guaranteed.",
            "the opening lead proves clubs are breaking."
          ]
        }
      ]
    },
    {
      "id": "G",
      "status": "fail",
      "findings": [
        {
          "dimension": "remaining resources",
          "fact": "The retained plan explicitly calls for dummy's clubs after both remaining dummy clubs must have been consumed.",
          "explanation": "North currently holds only CQ and C7. The selected C7 follows the current CA; North must then play CQ on South's CK. Dummy consequently has no remaining clubs for the next stated step. A feasible route using South's C8 and C6 does not validate the explicitly named dummy resource.",
          "quotes": [
            "Cash CA and CK as club controls, then use dummy’s remaining clubs to assess whether the suit is established.",
            "South’s CA wins the current trick; follow with C7 from dummy."
          ]
        }
      ]
    },
    {
      "id": "H",
      "status": "pass",
      "findings": [
        {
          "dimension": "remaining route and action consistency",
          "fact": "The replacement correctly uses dummy's remaining clubs under South's honors and continues from South.",
          "explanation": "CA is already in the current trick, so C7 follows it now; CQ can follow CK next. South retains C8 and C6 to cash if defensive clubs have fallen. Two diamond tricks already won, four club tricks and SA HA HK provide nine on that condition, with an obvious heart entry to HK.",
          "quotes": [
            "Cash South’s CA and CK while dummy follows with C7 and CQ; then cash South’s remaining clubs if the defenders’ clubs have fallen.",
            "Preserve the heart winners and SA."
          ]
        }
      ]
    },
    {
      "id": "I",
      "status": "pass",
      "findings": [
        {
          "dimension": "continuing plan and feasible remainder",
          "fact": "The retained plan's earlier steps match completed events, and its unfinished route is feasible.",
          "explanation": "The event history records South winning DK, losing the first club to West's C9, winning DA and leading CA. These are historical steps, not instructions to replay cards. C7 follows CA now, CQ can follow CK, and South retains C8 C6 for the conditional continuation. With SA HA HK, that route supplies nine total tricks if the defensive clubs fall.",
          "quotes": [
            "After an opponent wins that club round and South wins another diamond, cash South’s CA and CK while dummy follows; then cash South’s remaining clubs if defenders’ clubs have fallen.",
            "South’s CA wins the current trick; follow with C7 from dummy."
          ]
        }
      ]
    }
  ]
}
